arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) echo "x-access-token" ;;
  *[Pp]assword*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh && cd /home/runner/work/joey-conv && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/joey 2>&1 | tail -5 && git log --oneline -1
